using System;
using System.IO;
using System.Collections.Generic;
namespace AfterDarkClassic {
 sealed class PackageFiles:IDisposable {
  string root,backup;Dictionary<string,bool> touched=new Dictionary<string,bool>(StringComparer.OrdinalIgnoreCase);bool committed;
  public PackageFiles(string target){root=ValidateRoot(target);backup=Path.Combine(Path.GetTempPath(),"AfterDark-Rollback-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(backup);Directory.CreateDirectory(root);}
  public static string ValidateRoot(string target){string full=Path.GetFullPath(target).TrimEnd('\\');if(string.Equals(full,Path.GetPathRoot(full).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))throw new IOException("Elegí una carpeta para After Dark.");if(Directory.Exists(full)&&(File.GetAttributes(full)&FileAttributes.ReparsePoint)!=0)throw new IOException("La carpeta de instalación no puede ser un enlace.");return full;}
  public static string Inside(string root,string relative){string full=Path.GetFullPath(Path.Combine(root,relative));if(!full.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("Ruta fuera de la carpeta de instalación.");if(File.Exists(full)&&(File.GetAttributes(full)&FileAttributes.ReparsePoint)!=0)throw new IOException("No se pueden sobrescribir enlaces.");string dir=Path.GetDirectoryName(full);while(dir!=null&&dir.Length>=root.Length){if(Directory.Exists(dir)&&(File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)throw new IOException("No se pueden seguir enlaces dentro de la instalación.");if(string.Equals(dir,root,StringComparison.OrdinalIgnoreCase))break;dir=Path.GetDirectoryName(dir);}return full;}
  void Remember(string relative){if(touched.ContainsKey(relative))return;string dest=Inside(root,relative);bool exists=File.Exists(dest);if(exists){string copy=Inside(backup,relative);Directory.CreateDirectory(Path.GetDirectoryName(copy));File.Copy(dest,copy);}touched.Add(relative,exists);}
  public void Put(string relative,string source){Remember(relative);string dest=Inside(root,relative);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(source,dest,true);}
  public void Delete(string relative){Remember(relative);string dest=Inside(root,relative);if(File.Exists(dest))File.Delete(dest);}
  public void Commit(){committed=true;}
  public void Dispose(){try{if(!committed){foreach(var pair in touched){string dest=Inside(root,pair.Key);if(pair.Value)File.Copy(Inside(backup,pair.Key),dest,true);else if(File.Exists(dest))File.Delete(dest);}Prune(root,false);}}finally{CleanScratch(backup);}}
  public static void CleanScratch(string folder){string verified=Path.GetFullPath(folder);string temp=Path.GetFullPath(Path.GetTempPath()).TrimEnd('\\')+"\\";if(!verified.StartsWith(temp,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(verified).StartsWith("AfterDark-",StringComparison.Ordinal))throw new IOException("Ruta temporal inválida.");Directory.Delete(verified,true);}
  public static void Prune(string target,bool removeRoot){string root=ValidateRoot(target);if(!Directory.Exists(root))return;foreach(string child in Directory.GetDirectories(root)){if((File.GetAttributes(child)&FileAttributes.ReparsePoint)!=0)continue;Prune(child,true);}if(removeRoot&&Directory.GetFileSystemEntries(root).Length==0)Directory.Delete(root);}
  public static void SelfTest(string target){string root=Path.GetFullPath(target);Directory.CreateDirectory(root);string install=Path.Combine(root,"installed"),source=Path.Combine(root,"new.bin");Directory.CreateDirectory(install);File.WriteAllText(source,"new");File.WriteAllText(Path.Combine(install,"control.exe"),"old");File.WriteAllText(Path.Combine(install,"settings.ini"),"preserve");File.WriteAllText(Path.Combine(install,"foreign.txt"),"keep");using(var t=new PackageFiles(install)){t.Put("control.exe",source);t.Put("added.dll",source);}if(File.ReadAllText(Path.Combine(install,"control.exe"))!="old"||File.Exists(Path.Combine(install,"added.dll")))throw new Exception("Rollback failed");using(var t=new PackageFiles(install)){t.Put("control.exe",source);t.Put("sub\\added.dll",source);t.Commit();}if(File.ReadAllText(Path.Combine(install,"control.exe"))!="new"||File.ReadAllText(Path.Combine(install,"settings.ini"))!="preserve"||File.ReadAllText(Path.Combine(install,"foreign.txt"))!="keep")throw new Exception("Preservation failed");bool blocked=false;try{Inside(install,"..\\escape.txt");}catch(IOException){blocked=true;}if(!blocked)throw new Exception("Path traversal accepted");File.Delete(Path.Combine(install,"control.exe"));File.Delete(Path.Combine(install,"sub","added.dll"));Prune(install,true);if(!Directory.Exists(install)||Directory.Exists(Path.Combine(install,"sub")))throw new Exception("Cleanup failed");File.Delete(Path.Combine(install,"settings.ini"));File.Delete(Path.Combine(install,"foreign.txt"));Prune(install,true);if(Directory.Exists(install))throw new Exception("Root not removed");File.WriteAllText(Path.Combine(root,"result.txt"),"PASS: overwrite, rollback, settings and foreign-file preservation, path containment, empty-directory cleanup.");}
 }
}
